          queryCache: {
            getOrSet: jest.fn(async (key: string, fn: () => Promise<unknown>, _ttl?: number) => {
              if (cache.has(key)) return cache.get(key);
              const result = await fn();
              cache.set(key, result);
              return result;
            }),
            get: jest.fn((key: string) => cache.get(key)),
