/**
 * CONTROLADOR DE AUTENTICACIÓN PARA VENDEDORES/COMERCIALES
 * Maneja endpoints de login, logout, refresh y perfil
 */

import { Request, Response } from 'express';
import { authService } from '../services/auth.service';
import { rolesService } from '../services/roles.service';
import { logger, createRequestLogger } from '../utils/logger';
import { asyncHandler } from '../middleware/error.middleware';

/**
 * POST /api/auth/login
 * Login de vendedor/comercial (código o nombre + PIN)
 * Detecta automáticamente el rol: JEFE, COMERCIAL o REPARTIDOR
 */
export const login = asyncHandler(async (req: Request, res: Response): Promise<void> => {
  const requestId = req.requestId || '';
  const log = createRequestLogger(requestId);

  // Aceptar varios formatos (Flutter envía username/password)
  const usuario = req.body.username || req.body.usuario || req.body.codigoCliente || req.body.codigoVendedor || req.body.codigo;
  const password = req.body.password || req.body.nif || req.body.pin;

  if (!usuario || !password) {
    res.status(400).json({
      success: false,
      error: 'Usuario/código y PIN son requeridos',
    });
    return;
  }

  const metadata = {
    ip: req.ip || 'unknown',
    userAgent: req.get('user-agent') || 'unknown',
  };

  log.info('Intento de login vendedor', { usuario });

  const resultado = await authService.autenticarComercial(usuario, password, metadata);

  if (!resultado.success) {
    log.warn('Login fallido', { usuario, error: resultado.error });
    res.status(401).json({
      success: false,
      error: resultado.error,
      bloqueado: resultado.bloqueado || false,
      requires_reauth: true,
    });
    return;
  }

  // Generar tokens con datos del vendedor
  const tokens = authService.generarTokens(resultado.vendedor!);

  // ============================================
  // DETECCIÓN AUTOMÁTICA DE ROL
  // ============================================
  // rolesService.detectarRol() consulta los flags de movilidad del ERP
  // (DSEDAC.VDDX); no se infieren perfiles por código o actividad.
  const codigoVendedor = resultado.vendedor!.codigoVendedor;
  const rol = await rolesService.detectarRol(codigoVendedor);
  const codigoConductor = rol === 'REPARTIDOR' ? codigoVendedor : undefined;

  log.info('Login exitoso', {
    codigoVendedor: resultado.vendedor!.codigoVendedor,
    nombreVendedor: resultado.vendedor!.nombreVendedor,
    rol,
  });

  res.json({
    success: true,
    mensaje: 'Login exitoso',
    vendedor: resultado.vendedor,
    // Objeto user con toda la info para Flutter
    user: {
      id: resultado.vendedor!.codigoVendedor,
      code: resultado.vendedor!.codigoVendedor,
      name: resultado.vendedor!.nombreVendedor,
      company: 'GMP',
      delegation: null,
      vendedorCode: resultado.vendedor!.codigoVendedor,
      isJefeVentas: rol === 'JEFE',
      tipoVendedor: rol,
      role: rol, // JEFE, COMERCIAL, REPARTIDOR
      codigoConductor,
    },
    // También enviar rol a nivel raíz para fácil acceso
    role: rol,
    isJefeVentas: rol === 'JEFE',
    isRepartidor: rol === 'REPARTIDOR',
    codigoConductor,
    // Compatibilidad anterior
    usuario: {
      codigoUsuario: resultado.vendedor!.codigoVendedor,
      nombreUsuario: resultado.vendedor!.nombreVendedor,
      subempresa: 'GMP',
    },
    cliente: {
      codigo: resultado.vendedor!.codigoVendedor,
      nombre: resultado.vendedor!.nombreVendedor,
      nombreAlternativo: 'Vendedor',
      nif: resultado.vendedor!.nif,
      direccion: resultado.vendedor!.direccion,
      poblacion: resultado.vendedor!.poblacion,
      provincia: resultado.vendedor!.provincia,
      codigoPostal: '',
      telefono1: resultado.vendedor!.telefono,
      telefono2: '',
      recargo: false,
      exentoIva: false,
      codigoRuta: '',
      activo: true,
    },
    ...tokens,
  });
});

/**
 * POST /api/auth/refresh
 * Refrescar tokens
 */
export const refreshToken = asyncHandler(async (req: Request, res: Response): Promise<void> => {
  const { refreshToken } = req.body;

  const nuevosPares = await authService.refrescarTokens(refreshToken);

  if (!nuevosPares) {
    res.status(401).json({
      success: false,
      error: 'Refresh token inválido o expirado',
      code: 'INVALID_REFRESH_TOKEN',
    });
    return;
  }

  res.json({
    success: true,
    mensaje: 'Tokens refrescados',
    ...nuevosPares,
  });
});

/**
 * POST /api/auth/logout
 * Cerrar sesión
 */
export const logout = asyncHandler(async (req: Request, res: Response): Promise<void> => {
  const codigoUsuario = (req as any).user?.codigoUsuario;

  logger.info(`Logout exitoso: ${codigoUsuario || 'unknown'}`);

  res.json({
    success: true,
    mensaje: 'Logout exitoso',
  });
});

/**
 * GET /api/auth/perfil
 * Obtener perfil del usuario autenticado
 */
export const obtenerPerfil = asyncHandler(async (req: Request, res: Response): Promise<void> => {
  const user = (req as any).user;

  if (!user) {
    res.status(401).json({
      success: false,
      error: 'No autenticado',
    });
    return;
  }

  res.json({
    success: true,
    perfil: {
      codigoUsuario: user.codigoUsuario,
      nombreUsuario: user.nombreUsuario,
      subempresa: user.subempresa,
    },
  });
});

