/**
 * JOB CRON: TRANSFERENCIAS PROGRAMADAS
 * Procesa transferencias automáticas y alertas de CTR vencidos
 * 
 * Ejecuta diariamente a las 06:00 AM
 */

import schedule from 'node-schedule';
import { randomUUID } from 'crypto';
import { odbcPool } from '../config/database';
import { logger } from '../utils/logger';

// ============================================
// CONFIGURACIÓN
// ============================================

const CONFIG = {
    // Hora de ejecución (06:00 AM)
    HORA_EJECUCION: '0 6 * * *',
    // Días de gracia para CTR
    DIAS_GRACIA_CTR: 3,
    // Habilitar/deshabilitar jobs
    ENABLED: process.env.CRON_ENABLED !== 'false'
};

// ============================================
// INTERFACES
// ============================================

interface TransferenciaProgramada {
    id: string;
    codigoCliente: string;
    diaMes: number;
    importe: number;
    estado: 'PENDIENTE' | 'PROCESADA' | 'ERROR';
}

interface CTRPendiente {
    cliente: string;
    nombreCliente: string;
    albaran: number;
    importe: number;
    diasPendiente: number;
}

// ============================================
// FUNCIONES DE PROCESAMIENTO
// ============================================

/**
 * Procesa transferencias programadas para el día actual
 */
async function procesarTransferenciasProgramadas(): Promise<void> {
    const diaActual = new Date().getDate();

    logger.info(`[CRON] Procesando transferencias programadas para día ${diaActual}`);

    try {
        // Buscar transferencias programadas para hoy
        const transferencias = await odbcPool.query<Record<string, unknown>[]>(
            `SELECT 
        ID, CODIGO_CLIENTE, DIA_MES, IMPORTE, ESTADO
      FROM JAVIER.TRANSFERENCIAS_PROGRAMADAS
      WHERE DIA_MES = ?
        AND ESTADO = 'PENDIENTE'`,
            [diaActual]
        );

        logger.info(`[CRON] Encontradas ${transferencias.length} transferencias para procesar`);

        for (const trans of transferencias) {
            try {
                // Crear registro de cobro por transferencia
                const cobroId = randomUUID();

                await odbcPool.query(
                    `INSERT INTO JAVIER.COBROS (
            ID, CODIGO_CLIENTE, REFERENCIA, IMPORTE, FORMA_PAGO,
            OBSERVACIONES, FECHA, ORIGEN
          ) VALUES (?, ?, ?, ?, 'TRANSFERENCIA', ?, CURRENT_TIMESTAMP, 'CRON')`,
                    [
                        cobroId,
                        trans.CODIGO_CLIENTE,
                        `TRANS-AUTO-${diaActual}`,
                        trans.IMPORTE,
                        `Transferencia automática programada día ${diaActual}`
                    ]
                );

                // Marcar transferencia como procesada
                await odbcPool.query(
                    `UPDATE JAVIER.TRANSFERENCIAS_PROGRAMADAS
           SET ESTADO = 'PROCESADA', FECHA_PROCESO = CURRENT_TIMESTAMP
           WHERE ID = ?`,
                    [trans.ID]
                );

                logger.info(`[CRON] Transferencia procesada: ${trans.ID} - Cliente: ${trans.CODIGO_CLIENTE}`);

            } catch (error) {
                logger.error(`[CRON] Error procesando transferencia ${trans.ID}:`, error);

                // Marcar como error
                try {
                    await odbcPool.query(
                        `UPDATE JAVIER.TRANSFERENCIAS_PROGRAMADAS
             SET ESTADO = 'ERROR', OBSERVACIONES = ?
             WHERE ID = ?`,
                        [`Error: ${error instanceof Error ? error.message : 'Desconocido'}`, trans.ID]
                    );
                } catch { /* ignore */ }
            }
        }

        logger.info(`[CRON] Proceso de transferencias completado`);

    } catch (error) {
        if (error instanceof Error && error.message.includes('not found')) {
            logger.warn('[CRON] Tabla TRANSFERENCIAS_PROGRAMADAS no existe. Saltando...');
        } else {
            logger.error('[CRON] Error en procesarTransferenciasProgramadas:', error);
        }
    }
}

/**
 * Detecta y alerta sobre CTR vencidos
 */
async function alertarCTRVencidos(): Promise<void> {
    logger.info('[CRON] Verificando CTR vencidos...');

    try {
        // Buscar albaranes CTR con más de X días sin cobrar
        const ctrPendientes = await odbcPool.query<Record<string, unknown>[]>(
            `SELECT
        CAC.CODIGOCLIENTEFACTURA as CLIENTE,
        CLI.NOMCLI as NOMBRE_CLIENTE,
        CAC.NUMEROALBARAN,
        COALESCE(CVC.IMPORTEPENDIENTE, CAC.IMPORTETOTAL) as IMPORTE,
        DAYS(CURRENT_DATE) - DAYS(
          DATE(
            CAC.ANODOCUMENTO || '-' ||
            LPAD(CAST(CAC.MESDOCUMENTO AS VARCHAR(2)), 2, '0') || '-' ||
            LPAD(CAST(CAC.DIADOCUMENTO AS VARCHAR(2)), 2, '0')
          )
        ) as DIAS_PENDIENTE
      FROM DSEDAC.CAC
      LEFT JOIN DSEDAC.CVC 
        ON CVC.SUBEMPRESADOCUMENTO = CAC.SUBEMPRESAALBARAN
        AND CVC.EJERCICIODOCUMENTO = CAC.EJERCICIOALBARAN
        AND CVC.SERIEDOCUMENTO = CAC.SERIEFACTURA
        AND CVC.NUMERODOCUMENTO = CAC.NUMEROFACTURA
      LEFT JOIN DSEDAC.CLI ON TRIM(CLI.CODCLI) = TRIM(CAC.CODIGOCLIENTEFACTURA)
      WHERE (
        UPPER(TRIM(CAC.CODIGOFORMAPAGO)) LIKE '%CTR%'
        OR UPPER(TRIM(CAC.CODIGOFORMAPAGO)) LIKE '%REEMB%'
      )
      AND COALESCE(CVC.IMPORTEPENDIENTE, CAC.IMPORTETOTAL) > 0
      AND DAYS(CURRENT_DATE) - DAYS(
        DATE(
          CAC.ANODOCUMENTO || '-' ||
          LPAD(CAST(CAC.MESDOCUMENTO AS VARCHAR(2)), 2, '0') || '-' ||
          LPAD(CAST(CAC.DIADOCUMENTO AS VARCHAR(2)), 2, '0')
        )
      ) > ?
      ORDER BY DIAS_PENDIENTE DESC
      FETCH FIRST 50 ROWS ONLY`,
            [CONFIG.DIAS_GRACIA_CTR]
        );

        if (ctrPendientes.length > 0) {
            logger.warn(`[CRON] ⚠️ ALERTA: ${ctrPendientes.length} CTR vencidos encontrados`);

            const alertas: CTRPendiente[] = ctrPendientes.map(row => ({
                cliente: String(row.CLIENTE).trim(),
                nombreCliente: String(row.NOMBRE_CLIENTE || '').trim(),
                albaran: Number(row.NUMEROALBARAN),
                importe: parseFloat(String(row.IMPORTE)) || 0,
                diasPendiente: Number(row.DIAS_PENDIENTE)
            }));

            // Log de alertas
            alertas.forEach(ctr => {
                logger.warn(
                    `[CTR VENCIDO] Cliente: ${ctr.cliente} (${ctr.nombreCliente}) - ` +
                    `Albarán: ${ctr.albaran} - Importe: ${ctr.importe.toFixed(2)}€ - ` +
                    `Días: ${ctr.diasPendiente}`
                );
            });

            // TODO: Aquí se podría integrar envío de email o notificación
            // await enviarNotificacionCTR(alertas);

            // Registrar alerta en tabla (si existe)
            try {
                await odbcPool.query(
                    `INSERT INTO JAVIER.ALERTAS_COBROS (
            ID, TIPO, FECHA, DETALLE
          ) VALUES (?, 'CTR_VENCIDO', CURRENT_TIMESTAMP, ?)`,
                    [randomUUID(), JSON.stringify(alertas)]
                );
            } catch { /* tabla puede no existir */ }
        } else {
            logger.info('[CRON] No hay CTR vencidos');
        }

    } catch (error) {
        logger.error('[CRON] Error en alertarCTRVencidos:', error);
    }
}

/**
 * Reconcilia reposicionamientos pendientes
 */
async function reconciliarReposicionamientos(): Promise<void> {
    logger.info('[CRON] Reconciliando reposicionamientos...');

    try {
        // Buscar clientes con reposicionamiento activo
        // Este es un placeholder - ajustar según lógica de negocio real
        const reposiciones = await odbcPool.query<Record<string, unknown>[]>(
            `SELECT 
        CODIGO_CLIENTE, TIPO_REPOSICION, FRECUENCIA_DIAS
      FROM JAVIER.REPOSICIONAMIENTOS
      WHERE ESTADO = 'ACTIVO'
        AND PROXIMA_FECHA <= CURRENT_DATE`
        );

        logger.info(`[CRON] ${reposiciones.length} reposicionamientos a procesar`);

        // Procesar cada reposicionamiento
        for (const repo of reposiciones) {
            logger.info(`[CRON] Procesando reposicionamiento: ${repo.CODIGO_CLIENTE}`);
            // TODO: Implementar lógica de reposicionamiento según necesidades
        }

    } catch (error) {
        if (error instanceof Error && error.message.includes('not found')) {
            logger.debug('[CRON] Tabla REPOSICIONAMIENTOS no existe. Saltando...');
        } else {
            logger.error('[CRON] Error en reconciliarReposicionamientos:', error);
        }
    }
}

// ============================================
// INICIALIZACIÓN DEL JOB
// ============================================

/**
 * Inicializa los jobs cron
 */
export function iniciarJobsCobros(): void {
    if (!CONFIG.ENABLED) {
        logger.info('[CRON] Jobs de cobros deshabilitados por configuración');
        return;
    }

    logger.info('[CRON] Iniciando jobs de cobros...');

    // Job principal: 06:00 AM cada día
    schedule.scheduleJob('cobros-diario', CONFIG.HORA_EJECUCION, async () => {
        logger.info('[CRON] ═══════════════════════════════════════');
        logger.info('[CRON] Iniciando proceso diario de cobros...');
        logger.info('[CRON] ═══════════════════════════════════════');

        try {
            await procesarTransferenciasProgramadas();
            await alertarCTRVencidos();
            await reconciliarReposicionamientos();

            logger.info('[CRON] ═══════════════════════════════════════');
            logger.info('[CRON] Proceso diario completado exitosamente');
            logger.info('[CRON] ═══════════════════════════════════════');

        } catch (error) {
            logger.error('[CRON] Error en proceso diario:', error);
        }
    });

    logger.info(`[CRON] Job programado: cobros-diario (${CONFIG.HORA_EJECUCION})`);
}

/**
 * Detiene los jobs cron
 */
export function detenerJobsCobros(): void {
    const job = schedule.scheduledJobs['cobros-diario'];
    if (job) {
        job.cancel();
        logger.info('[CRON] Job cobros-diario cancelado');
    }
}

/**
 * Ejecuta el proceso manualmente (para testing)
 */
export async function ejecutarProcesoManual(): Promise<void> {
    logger.info('[CRON] Ejecutando proceso manual...');
    await procesarTransferenciasProgramadas();
    await alertarCTRVencidos();
    await reconciliarReposicionamientos();
    logger.info('[CRON] Proceso manual completado');
}

export default {
    iniciarJobsCobros,
    detenerJobsCobros,
    ejecutarProcesoManual
};

/**
 * MIDDLEWARE DE AUTENTICACIÓN
 * Verifica tokens JWT y autorización por roles para vendedores/comerciales
 */

import { Request, Response, NextFunction } from 'express';
import { authService } from '../services/auth.service';
import { logger } from '../utils/logger';

// Extender Request para incluir usuario autenticado (vendedor)
declare global {
  namespace Express {
    interface Request {
      user?: {
        codigoVendedor: string;
        nombreVendedor: string;
        jti: string;
      };
      requestId?: string;
    }
  }
}

/**
 * Middleware que requiere autenticación JWT
 */
export function requireAuth(req: Request, res: Response, next: NextFunction): void {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.status(401).json({
        success: false,
        error: 'Token de autenticación requerido',
        code: 'MISSING_TOKEN',
      });
      return;
    }

    const token = authHeader.split(' ')[1];
    const decoded = authService.verificarAccessToken(token);

    if (!decoded) {
      res.status(401).json({
        success: false,
        error: 'Token inválido o expirado',
        code: 'INVALID_TOKEN',
      });
      return;
    }

    // Agregar vendedor al request
    req.user = {
      codigoVendedor: decoded.codigoVendedor,
      nombreVendedor: decoded.nombreVendedor,
      jti: decoded.jti,
    };

    next();
  } catch (error) {
    logger.error('Error en autenticación:', error);
    res.status(401).json({
      success: false,
      error: 'Error de autenticación',
      code: 'AUTH_ERROR',
    });
  }
}

/**
 * Middleware que verifica ownership del recurso
 * El vendedor solo puede acceder a sus propios datos
 */
export function requireOwnership(req: Request, res: Response, next: NextFunction): void {
  try {
    const { codigoVendedor } = req.params;
    const vendedorAutenticado = req.user?.codigoVendedor;

    if (!vendedorAutenticado) {
      res.status(401).json({
        success: false,
        error: 'No autenticado',
        code: 'NOT_AUTHENTICATED',
      });
      return;
    }

    // Comparar códigos normalizados
    const codigoNormalizado = String(codigoVendedor).trim().toUpperCase();
    const usuarioNormalizado = String(vendedorAutenticado).trim().toUpperCase();

    if (codigoNormalizado !== usuarioNormalizado) {
      logger.warn(`Intento de acceso no autorizado: ${vendedorAutenticado} -> ${codigoVendedor}`);
      res.status(403).json({
        success: false,
        error: 'No tienes permiso para acceder a este recurso',
        code: 'FORBIDDEN',
      });
      return;
    }

    next();
  } catch (error) {
    logger.error('Error verificando ownership:', error);
    res.status(500).json({
      success: false,
      error: 'Error verificando permisos',
    });
  }
}

/**
 * Middleware opcional de autenticación
 * No falla si no hay token, pero lo verifica si existe
 */
export function optionalAuth(req: Request, _res: Response, next: NextFunction): void {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      next();
      return;
    }

    const token = authHeader.split(' ')[1];
    const decoded = authService.verificarAccessToken(token);

    if (decoded) {
      req.user = {
        codigoVendedor: decoded.codigoVendedor,
        nombreVendedor: decoded.nombreVendedor,
        jti: decoded.jti,
      };
    }

    next();
  } catch {
    // Token inválido, continuar sin usuario
    next();
  }
}

/**
 * Middleware de autorización por roles
 * @param _rolesPermitidos - Array de roles que pueden acceder
 */
export function requireRole(..._rolesPermitidos: string[]) {
  return (req: Request, res: Response, next: NextFunction): void => {
    // Por ahora, todos los vendedores autenticados tienen el mismo rol
    // En el futuro se puede expandir para roles: comercial, administrador, supervisor
    
    if (!req.user) {
      res.status(401).json({
        success: false,
        error: 'No autenticado',
        code: 'NOT_AUTHENTICATED',
      });
      return;
    }

    // TODO: Implementar verificación de roles cuando se agregue la tabla de roles
    // Por ahora, permitir acceso si está autenticado
    next();
  };
}

export default {
  requireAuth,
  requireOwnership,
  optionalAuth,
  requireRole,
};

/**
 * MIDDLEWARE DE MANEJO DE ERRORES
 * Gestión centralizada de errores y respuestas
 */

import { Request, Response, NextFunction } from 'express';
import { logger } from '../utils/logger';
import { config } from '../config/env';

/**
 * Clase personalizada para errores de la API
 */
export class ApiError extends Error {
  statusCode: number;
  code: string;
  isOperational: boolean;

  constructor(
    message: string,
    statusCode: number = 500,
    code: string = 'INTERNAL_ERROR',
    isOperational: boolean = true
  ) {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Errores predefinidos
 */
export const Errors = {
  NotFound: (message = 'Recurso no encontrado') => 
    new ApiError(message, 404, 'NOT_FOUND'),
  
  Unauthorized: (message = 'No autorizado') => 
    new ApiError(message, 401, 'UNAUTHORIZED'),
  
  Forbidden: (message = 'Acceso prohibido') => 
    new ApiError(message, 403, 'FORBIDDEN'),
  
  BadRequest: (message = 'Petición inválida') => 
    new ApiError(message, 400, 'BAD_REQUEST'),
  
  Validation: (message = 'Error de validación') => 
    new ApiError(message, 400, 'VALIDATION_ERROR'),
  
  RateLimit: (message = 'Límite de peticiones excedido') => 
    new ApiError(message, 429, 'RATE_LIMIT'),
  
  Internal: (message = 'Error interno del servidor') => 
    new ApiError(message, 500, 'INTERNAL_ERROR', false),
  
  Database: (message = 'Error de base de datos') => 
    new ApiError(message, 500, 'DATABASE_ERROR', false),
};

/**
 * Middleware para rutas no encontradas
 */
export function notFoundHandler(req: Request, res: Response, _next: NextFunction): void {
  logger.warn(`Ruta no encontrada: ${req.method} ${req.path}`);
  
  res.status(404).json({
    success: false,
    error: 'Endpoint no encontrado',
    code: 'NOT_FOUND',
    path: req.path,
    method: req.method,
  });
}

/**
 * Middleware principal de manejo de errores
 */
export function errorHandler(
  err: Error | ApiError,
  req: Request,
  res: Response,
  _next: NextFunction
): void {
  // Determinar si es un error operacional o de programación
  const isApiError = err instanceof ApiError;
  const statusCode = isApiError ? err.statusCode : 500;
  const code = isApiError ? err.code : 'INTERNAL_ERROR';
  const isOperational = isApiError ? err.isOperational : false;

  // Logging
  if (isOperational) {
    logger.warn(`Error operacional [${code}]:`, {
      message: err.message,
      path: req.path,
      method: req.method,
      requestId: req.requestId,
    });
  } else {
    logger.error('Error no manejado:', {
      message: err.message,
      stack: err.stack,
      path: req.path,
      method: req.method,
      requestId: req.requestId,
    });
  }

  // Respuesta al cliente
  const response: Record<string, unknown> = {
    success: false,
    error: isOperational ? err.message : 'Error interno del servidor',
    code,
    requestId: req.requestId,
  };

  // En desarrollo, incluir stack trace
  if (config.isDevelopment && !isOperational) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
}

/**
 * Logger de peticiones
 */
export function requestLogger(req: Request, res: Response, next: NextFunction): void {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    const level = res.statusCode >= 400 ? 'warn' : 'info';

    logger[level](`${req.method} ${req.path}`, {
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      requestId: req.requestId,
      ip: req.ip,
    });
  });

  next();
}

/**
 * Wrapper para async handlers
 * Captura errores de funciones async y los pasa al error handler
 */
export function asyncHandler(
  fn: (req: Request, res: Response, next: NextFunction) => Promise<void>
) {
  return (req: Request, res: Response, next: NextFunction): void => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

export default {
  ApiError,
  Errors,
  notFoundHandler,
  errorHandler,
  requestLogger,
  asyncHandler,
};

/**
 * COMMISSIONS ROUTES - Refactored from legacy commissions.js (1087 lines → ~90 lines)
 *
 * Endpoints:
 *   GET  /api/commissions/summary         - Commission breakdown by vendor/year
 *   POST /api/commissions/pay             - Record commission payment
 *   GET  /api/commissions/excluded-vendors - List excluded vendor codes
 *   GET  /api/commissions/team/80          - Team commission for commercial 80 (Almeria lead)
 *
 * SECURITY: Joi validation + parameterized queries via service layer.
 */

import { Router, Request, Response, NextFunction } from 'express';
import { commissionsService, getTeamCommission, loadTeamCommissionConfig } from '../services/commissions.service';
import { validate } from '../middleware/validation.middleware';
import { schemas } from '../utils/validators';
import { requireAuth, requireRole } from '../middleware/auth.middleware';
import { generalLimiter } from '../middleware/security.middleware';
import { logger } from '../utils/logger';

const router = Router();

/**
 * GET /api/commissions/summary
 * Full commission breakdown for one or many vendors across one or more years.
 */
router.get('/summary',
  requireAuth,
  generalLimiter,
  validate(schemas.commissionsSummaryQuery, 'query'),
  async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const vendorCode = req.query.vendedorCode as string;
      const yearParam = req.query.year as string | undefined;

      // Parse years (supports comma-separated)
      const currentYear = new Date().getFullYear();
      let years: number[];
      if (yearParam) {
        years = yearParam.split(',')
          .map(y => parseInt(y.trim(), 10))
          .filter(n => !isNaN(n) && n >= 2020 && n <= currentYear + 1);
      } else {
        years = [currentYear];
      }
      if (years.length === 0) years = [currentYear];

      const result = await commissionsService.getSummary(vendorCode, years);

      res.json({ success: true, ...result });
    } catch (error) {
      logger.error('Error en GET /commissions/summary:', error);
      next(error);
    }
  },
);

/**
 * POST /api/commissions/pay
 * Register a commission payment (admin only).
 */
router.post('/pay',
  requireAuth,
  generalLimiter,
  validate(schemas.commissionsPayBody, 'body'),
  async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { vendedorCode, year, month, amount, generatedAmount, observaciones, adminCode, objetivoMes, ventasSobreObjetivo } = req.body;

      // Verify admin authorization
      const callerCode = adminCode || req.user?.codigoVendedor || '';
      const isAuthorized = await commissionsService.verifyAdminAuth(callerCode);
      if (!isAuthorized) {
        logger.warn(`[COMMISSIONS] Unauthorized payment attempt by: ${callerCode}`);
        res.status(403).json({ success: false, error: 'No tienes permisos para registrar pagos.' });
        return;
      }

      const result = await commissionsService.recordPayment({
        vendedorCode, year, month: month || 0,
        amount: parseFloat(amount), generatedAmount: parseFloat(generatedAmount) || 0,
        observaciones, adminCode: callerCode,
        objetivoMes: parseFloat(objetivoMes) || 0,
        ventasSobreObjetivo: parseFloat(ventasSobreObjetivo) || 0,
      });

      res.json(result);
    } catch (error) {
      logger.error('Error en POST /commissions/pay:', error);
      next(error);
    }
  },
);

/**
 * GET /api/commissions/excluded-vendors
 * Returns list of vendor codes excluded from commissions.
 */
router.get('/excluded-vendors',
  requireAuth,
  async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const excludedVendors = await commissionsService.getExcludedVendors();
      res.json({ success: true, excludedVendors });
    } catch (error) {
      logger.error('Error en GET /commissions/excluded-vendors:', error);
      res.json({ success: true, excludedVendors: ['3', '13', '93'] });
    }
  },
);

/**
 * GET /api/commissions/team/:leaderCode
 * Team commission breakdown for a commercial leader.
 * Commission rate, threshold, and team members are DB-configurable
 * via JAVIER.TEAM_COMMISSION_RULES + TEAM_COMMISSION_MEMBERS.
 */
router.get('/team/:leaderCode',
  requireAuth,
  generalLimiter,
  async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const leaderCode = req.params.leaderCode;
      const yearParam = req.query.year as string | undefined;
      const currentYear = new Date().getFullYear();
      const year = yearParam ? parseInt(yearParam, 10) : currentYear;

      if (isNaN(year) || year < 2020 || year > currentYear + 1) {
        res.status(400).json({ success: false, error: 'Year invalido' });
        return;
      }

      const result = await getTeamCommission(leaderCode, year);
      res.json(result);
    } catch (error) {
      logger.error('Error en GET /commissions/team/:leaderCode:', error);
      next(error);
    }
  },
);

/**
 * GET /api/commissions/team/:leaderCode/members
 * Returns the list of vendor codes in a leader's team (from DB).
 */
router.get('/team/:leaderCode/members',
  requireAuth,
  async (req: Request, res: Response): Promise<void> => {
    try {
      const leaderCode = req.params.leaderCode;
      const currentYear = new Date().getFullYear();
      const config = await loadTeamCommissionConfig(leaderCode, currentYear);
      res.json({
        success: true,
        leaderCode,
        teamMembers: config.members.map(m => m.memberCode),
        config: {
          commissionRate: config.rule.commissionRate,
          growthThresholdPct: config.rule.growthThresholdPct,
          allMustQualify: config.rule.allMustQualify,
        },
      });
    } catch (error) {
      logger.error('Error en GET /commissions/team/:leaderCode/members:', error);
      res.status(500).json({ success: false, error: 'Error cargando miembros' });
    }
  },
);

export default router;

