      FROM DSEDAC.CFC CFC
      LEFT JOIN DSEDAC.CLI CLI ON TRIM(CLI.CODIGOCLIENTE) = TRIM(CFC.CODIGOCLIENTE)
      WHERE TRIM(CFC.SERIEFACTURA) = ?
