  /**
   * GET /history/documents/:clientId
   * Client document history with deduplication and status cascade.
   */
  async getDocumentHistory(params: {
    clientId: string; repartidorId?: string;
    year?: number; dateFrom?: string; dateTo?: string;
    limit?: number; offset?: number;
  }): Promise<Record<string, unknown>> {
    const safeClientId = sanitizeCode(params.clientId);
    const conditions: string[] = ['CPC.CODIGOCLIENTEALBARAN = ?'];
    const queryParams: unknown[] = [safeClientId];

    // Optional repartidor join
    let repartidorJoin = '';
    if (params.repartidorId) {
      const ids = params.repartidorId.split(',').map(id => sanitizeCode(id.trim()));
      const { clause, params: idParams } = buildInClause('TRIM(OPP.CODIGOREPARTIDOR)', ids);
      repartidorJoin = `
        INNER JOIN DSEDAC.OPP OPP
          ON OPP.NUMEROORDENPREPARACION = CPC.NUMEROORDENPREPARACION
          AND ${clause}`;
      queryParams.push(...idParams);
    }

    // Year filter
    if (params.year) {
      conditions.push('CPC.EJERCICIOALBARAN = ?');
      queryParams.push(params.year);
    }

    // Date range filters
    if (params.dateFrom) {
      const parts = params.dateFrom.split('-');
      if (parts.length === 3) {
        const numFrom = parseInt(parts[0]) * 10000 + parseInt(parts[1]) * 100 + parseInt(parts[2]);
        conditions.push('(CPC.ANODOCUMENTO * 10000 + CPC.MESDOCUMENTO * 100 + CPC.DIADOCUMENTO) >= ?');
        queryParams.push(numFrom);
      }
    }
    if (params.dateTo) {
      const parts = params.dateTo.split('-');
      if (parts.length === 3) {
        const numTo = parseInt(parts[0]) * 10000 + parseInt(parts[1]) * 100 + parseInt(parts[2]);
        conditions.push('(CPC.ANODOCUMENTO * 10000 + CPC.MESDOCUMENTO * 100 + CPC.DIADOCUMENTO) <= ?');
        queryParams.push(numTo);
      }
    }

    const whereClause = conditions.join(' AND ');

    // Check if DELIVERY_STATUS table is available
    let dsAvailable = false;
    try {
      const { isDeliveryStatusAvailable } = require('../../utils/delivery-status-check');
      dsAvailable = isDeliveryStatusAvailable();
    } catch { dsAvailable = false; }

    const dsJoin = dsAvailable
      ? `LEFT JOIN JAVIER.DELIVERY_STATUS DS ON
          DS.ID = TRIM(CAST(CPC.EJERCICIOALBARAN AS VARCHAR(10))) || '-' || TRIM(CPC.SERIEALBARAN) || '-' || TRIM(CAST(CPC.TERMINALALBARAN AS VARCHAR(10))) || '-' || TRIM(CAST(CPC.NUMEROALBARAN AS VARCHAR(10)))`
      : '';
    const dsStatusCol = dsAvailable ? 'DS.STATUS AS DELIVERY_STATUS' : "CAST(NULL AS VARCHAR(20)) AS DELIVERY_STATUS";
    const dsFirmaCol = dsAvailable ? 'DS.FIRMA_PATH' : "CAST(NULL AS VARCHAR(255)) AS FIRMA_PATH";
    const dsObsCol = dsAvailable ? 'DS.OBSERVACIONES' : "CAST(NULL AS VARCHAR(512)) AS OBSERVACIONES";

    const rows = await odbcPool.query<Record<string, unknown>[]>(`
      SELECT
        CPC.SUBEMPRESAALBARAN, CPC.EJERCICIOALBARAN, CPC.SERIEALBARAN,
        CPC.TERMINALALBARAN, CPC.NUMEROALBARAN,
        CPC.ANODOCUMENTO AS ANO, CPC.MESDOCUMENTO AS MES, CPC.DIADOCUMENTO AS DIA,
        CPC.CODIGOCLIENTEALBARAN, CPC.IMPORTETOTAL,
        COALESCE((
          SELECT SUM(CV.IMPORTEPENDIENTE) FROM DSEDAC.CVC CV
          WHERE CV.SUBEMPRESADOCUMENTO = CPC.SUBEMPRESAALBARAN
            AND CV.EJERCICIODOCUMENTO = CPC.EJERCICIOALBARAN
            AND CV.SERIEDOCUMENTO = CPC.SERIEALBARAN
            AND CV.NUMERODOCUMENTO = CPC.NUMEROALBARAN
        ), 0) AS IMPORTE_PENDIENTE,
        CPC.CONFORMADOSN, CPC.SITUACIONALBARAN, CPC.HORALLEGADA,
        ${dsStatusCol}, ${dsFirmaCol}, ${dsObsCol},
        COALESCE((SELECT CAC2.NUMEROFACTURA FROM DSEDAC.CAC CAC2
          WHERE CAC2.EJERCICIOALBARAN = CPC.EJERCICIOALBARAN AND CAC2.SERIEALBARAN = CPC.SERIEALBARAN
            AND CAC2.TERMINALALBARAN = CPC.TERMINALALBARAN AND CAC2.NUMEROALBARAN = CPC.NUMEROALBARAN
          FETCH FIRST 1 ROW ONLY), 0) AS NUMEROFACTURA,
        COALESCE((SELECT TRIM(CAC2.SERIEFACTURA) FROM DSEDAC.CAC CAC2
          WHERE CAC2.EJERCICIOALBARAN = CPC.EJERCICIOALBARAN AND CAC2.SERIEALBARAN = CPC.SERIEALBARAN
            AND CAC2.TERMINALALBARAN = CPC.TERMINALALBARAN AND CAC2.NUMEROALBARAN = CPC.NUMEROALBARAN
          FETCH FIRST 1 ROW ONLY), '') AS SERIEFACTURA,
        COALESCE((SELECT CAC2.EJERCICIOFACTURA FROM DSEDAC.CAC CAC2
          WHERE CAC2.EJERCICIOALBARAN = CPC.EJERCICIOALBARAN AND CAC2.SERIEALBARAN = CPC.SERIEALBARAN
            AND CAC2.TERMINALALBARAN = CPC.TERMINALALBARAN AND CAC2.NUMEROALBARAN = CPC.NUMEROALBARAN
          FETCH FIRST 1 ROW ONLY), 0) AS EJERCICIOFACTURA,
        COALESCE((SELECT FIRMANOMBRE FROM DSEDAC.CACFIRMAS
          WHERE EJERCICIOALBARAN = CPC.EJERCICIOALBARAN AND TRIM(SERIEALBARAN) = TRIM(CPC.SERIEALBARAN)
            AND TERMINALALBARAN = CPC.TERMINALALBARAN AND NUMEROALBARAN = CPC.NUMEROALBARAN
          FETCH FIRST 1 ROW ONLY), '') AS LEGACY_FIRMA_NOMBRE,
        (SELECT ANO FROM DSEDAC.CACFIRMAS
          WHERE EJERCICIOALBARAN = CPC.EJERCICIOALBARAN AND TRIM(SERIEALBARAN) = TRIM(CPC.SERIEALBARAN)
            AND TERMINALALBARAN = CPC.TERMINALALBARAN AND NUMEROALBARAN = CPC.NUMEROALBARAN
          FETCH FIRST 1 ROW ONLY) AS LEGACY_ANO
      FROM DSEDAC.CPC CPC
      ${repartidorJoin}
      ${dsJoin}
      WHERE ${whereClause}
      ORDER BY CPC.EJERCICIOALBARAN DESC, CPC.ANODOCUMENTO DESC,
        CPC.MESDOCUMENTO DESC, CPC.DIADOCUMENTO DESC, CPC.NUMEROALBARAN DESC
    `, queryParams);

    // Deduplication: group by unique albaran OR factura key
    const uniqueMap = new Map<string, Record<string, unknown>>();
    for (const row of rows) {
      const serie = toStr(row.SERIEALBARAN).trim();
      const numFactura = toInt(row.NUMEROFACTURA);
      const key = numFactura > 0
        ? `FAC-${row.EJERCICIOALBARAN}-${(toStr(row.SERIEFACTURA) || serie).trim()}-${numFactura}`
        : `ALB-${row.EJERCICIOALBARAN}-${serie}-${row.TERMINALALBARAN}-${row.NUMEROALBARAN}`;

      if (!uniqueMap.has(key)) {
        uniqueMap.set(key, row);
      } else if (numFactura > 0) {
        const existing = uniqueMap.get(key)!;
        if (toInt(row.NUMEROALBARAN) > toInt(existing.NUMEROALBARAN)) {
          uniqueMap.set(key, row);
        }
      }
    }

    const documents = Array.from(uniqueMap.values()).map(row => {
      const importe = toFloat(row.IMPORTETOTAL);
      const pendiente = toFloat(row.IMPORTE_PENDIENTE);
      const status = determineDeliveryStatus(row);
      const numFactura = toInt(row.NUMEROFACTURA);
      const isFactura = numFactura > 0;
      const serie = toStr(row.SERIEALBARAN).trim() || 'A';
      const legacyNombre = toStr(row.LEGACY_FIRMA_NOMBRE).trim();
      const hasLegacySig = legacyNombre.length > 0 || toInt(row.LEGACY_ANO) > 0;
      const hasFirmaPath = !!row.FIRMA_PATH;

      // Format time
      const hora = toInt(row.HORALLEGADA);
      let time: string | null = null;
      if (hora > 0) {
        const hStr = hora.toString().padStart(6, '0');
        time = `${hStr.substring(0, 2)}:${hStr.substring(2, 4)}`;
      }

      return {
        id: `${row.EJERCICIOALBARAN}-${serie}-${row.TERMINALALBARAN}-${row.NUMEROALBARAN}`,
        type: isFactura ? 'factura' : 'albaran',
        number: isFactura ? numFactura : toInt(row.NUMEROALBARAN),
        albaranNumber: toInt(row.NUMEROALBARAN),
        facturaNumber: numFactura || null,
        serieFactura: toStr(row.SERIEFACTURA).trim() || null,
        ejercicioFactura: toInt(row.EJERCICIOFACTURA) || null,
        serie, ejercicio: toInt(row.EJERCICIOALBARAN), terminal: toInt(row.TERMINALALBARAN),
        date: `${toInt(row.ANO)}-${String(toInt(row.MES)).padStart(2, '0')}-${String(toInt(row.DIA)).padStart(2, '0')}`,
        time, amount: importe, pending: pendiente, status,
        hasSignature: hasFirmaPath || hasLegacySig,
        signaturePath: toStr(row.FIRMA_PATH) || null,
        deliveryObs: toStr(row.OBSERVACIONES) || null,
        hasLegacySignature: hasLegacySig,
        legacySignatureName: legacyNombre || null,
      };
    });

    return { success: true, clientId: safeClientId, total: documents.length, documents };
  }

  /**
   * GET /history/objectives/:repartidorId
   * Historical monthly 30% threshold tracking.
   */
  async getHistoricalObjectives(params: {
    repartidorIds: string; clientId?: string;
  }): Promise<Record<string, unknown>> {
    const ids = params.repartidorIds.split(',').map(id => sanitizeCode(id.trim()));
    const { clause: idsClause, params: idsParams } = buildInClause('TRIM(OPP.CODIGOREPARTIDOR)', ids);

    const conditions = [idsClause];
    const queryParams = [...idsParams];

    if (params.clientId) {
      conditions.push('TRIM(CPC.CODIGOCLIENTEALBARAN) = ?');
      queryParams.push(sanitizeCode(params.clientId));
    }

    const rows = await odbcPool.query<Record<string, unknown>[]>(`
      SELECT
        OPP.ANOREPARTO AS ANO,
        OPP.MESREPARTO AS MES,
        SUM(CPC.IMPORTETOTAL) AS TOTAL_COBRABLE,
        SUM(CASE
          WHEN COALESCE(CVC.IMPORTEPENDIENTE, 0) = 0 THEN CPC.IMPORTETOTAL
          ELSE CPC.IMPORTETOTAL - COALESCE(CVC.IMPORTEPENDIENTE, 0)
        END) AS TOTAL_COBRADO
      FROM DSEDAC.OPP OPP
      INNER JOIN DSEDAC.CPC CPC ON CPC.NUMEROORDENPREPARACION = OPP.NUMEROORDENPREPARACION
      LEFT JOIN DSEDAC.CVC CVC
        ON CVC.SUBEMPRESADOCUMENTO = CPC.SUBEMPRESAALBARAN
        AND CVC.EJERCICIODOCUMENTO = CPC.EJERCICIOALBARAN
        AND CVC.SERIEDOCUMENTO = CPC.SERIEALBARAN
        AND CVC.NUMERODOCUMENTO = CPC.NUMEROALBARAN
      WHERE ${conditions.join(' AND ')}
      GROUP BY OPP.ANOREPARTO, OPP.MESREPARTO
      ORDER BY OPP.ANOREPARTO DESC, OPP.MESREPARTO DESC
    `, queryParams);

    const objectives = rows.map(row => {
      const collectable = toFloat(row.TOTAL_COBRABLE);
      const collected = toFloat(row.TOTAL_COBRADO);
      const percentage = collectable > 0 ? (collected / collectable) * 100 : 0;
      const mes = toInt(row.MES);

      return {
        month: `${MONTH_NAMES[mes - 1] || ''} ${toInt(row.ANO)}`,
        year: toInt(row.ANO),
        monthNum: mes,
        collectable, collected,
        percentage: parseFloat(percentage.toFixed(2)),
        thresholdMet: percentage >= REPARTIDOR_CONFIG.threshold,
      };
    });

    return { success: true, objectives };
  }

  /**
   * GET /config
   * Returns repartidor commission configuration.
   */
  getConfig(): Record<string, unknown> {
    return {
      success: true,
      config: REPARTIDOR_CONFIG,
    };
  }
}

export const repartidorService = new RepartidorService();

/**
 * SERVICIO DE ROLES - DETECCIÓN DESDE BD
 * 
 * Detecta roles leyendo los flags de movilidad del ERP en DSEDAC.VDDX:
 * - JEFEVENTASSN = 'S' → JEFE
 * - PERMITEREPARTOSN = 'S' sin preventa → REPARTIDOR
 * - En cualquier otro caso → COMERCIAL
 */

import { odbcPool } from '../config/database';
import { logger } from '../utils/logger';
import { toFloat, toInt, toStr } from '../utils/db-helpers';
import { queryCache, TTL } from '../utils/query-cache';

// Tipos de rol
export type UserRole = 'JEFE' | 'COMERCIAL' | 'REPARTIDOR';

export interface AppUser {
    codigo: string;
    nombre: string;
    rol: UserRole;
    codigoConductor?: string;
    rutasAsignadas?: string[];
}


// Códigos de forma de pago que requieren cobro (CTR)
const CODIGOS_CTR_TIPICOS = ['01', 'CO', 'EF', 'CT', 'CTR', 'CONTADO', 'EFECTIVO'];

class RolesService {

    /**
     * Detectar rol del usuario desde los flags de movilidad del ERP.
     */
    async detectarRol(codigoUsuario: string, _isJefeVentasFromLogin?: boolean): Promise<UserRole> {
        const codigo = codigoUsuario.trim();
        if (!codigo) return 'COMERCIAL';

        try {
            const resultado = await odbcPool.query<Record<string, unknown>[]>(`
        SELECT
          TRIM(PERMITEPREVENTASN) as PREVENTISTA_SN,
          TRIM(PERMITEREPARTOSN) as REPARTIDOR_SN,
          TRIM(JEFEVENTASSN) as JEFE_SN
        FROM DSEDAC.VDDX
        WHERE TRIM(CODIGOVENDEDOR) = ?
        FETCH FIRST 1 ROWS ONLY
      `, [codigo]);

            const row = resultado[0];
            if (!row) return 'COMERCIAL';
            const isYes = (value: unknown) => ['S', 'Y', '1', 'TRUE']
                .includes(toStr(value).trim().toUpperCase());
            const permitePreventa = isYes(row.PREVENTISTA_SN);
            const permiteReparto = isYes(row.REPARTIDOR_SN);
            const isJefeVentas = isYes(row.JEFE_SN);

            if (isJefeVentas) return 'JEFE';
            if (permiteReparto && !permitePreventa) return 'REPARTIDOR';
            return 'COMERCIAL';
        } catch (error) {
            // An unavailable profile must never be promoted by an ID, vehicle,
            // or delivery-history fallback.
            logger.error('[ROLES] Error leyendo flags de movilidad del ERP:', error);
            return 'COMERCIAL';
        }
    }

    /**
     * Obtener información completa del usuario con rol
     */
    async obtenerUsuarioConRol(codigoUsuario: string, nombre: string, isJefeVentasFromLogin?: boolean): Promise<AppUser> {
        const rol = await this.detectarRol(codigoUsuario, isJefeVentasFromLogin);

        return {
            codigo: codigoUsuario,
            nombre,
            rol,
            codigoConductor: rol === 'REPARTIDOR' ? codigoUsuario : undefined,
        };
    }

    /**
     * Obtener lista de conductores existentes (para selector en admin)
     */
    async obtenerConductores(): Promise<{ codigo: string; totalAlbaranes: number }[]> {
        return queryCache.getOrSet('gmp:roles:conductores', () => this._fetchConductores(), TTL.LONG);
    }

    private async _fetchConductores(): Promise<{ codigo: string; totalAlbaranes: number }[]> {
        try {
            // The ERP mobility flags are authoritative. Historical deliveries
            // may mention a person who is not an authorized driver.
            const resultado = await odbcPool.query<Record<string, unknown>[]>(`
        SELECT
          TRIM(X.CODIGOVENDEDOR) as CODIGO,
          COUNT(CAC.NUMEROALBARAN) as TOTAL
        FROM DSEDAC.VDDX X
        LEFT JOIN DSEDAC.CAC CAC
          ON TRIM(CAC.CODIGOCONDUCTOR) = TRIM(X.CODIGOVENDEDOR)
         AND CAC.EJERCICIOALBARAN = 2026
        WHERE TRIM(X.PERMITEREPARTOSN) = 'S'
          AND COALESCE(TRIM(X.PERMITEPREVENTASN), '') <> 'S'
          AND COALESCE(TRIM(X.JEFEVENTASSN), '') <> 'S'
          AND TRIM(X.CODIGOVENDEDOR) <> ''
        GROUP BY TRIM(X.CODIGOVENDEDOR)
        ORDER BY TOTAL DESC
        FETCH FIRST 50 ROWS ONLY
      `);

            return resultado.map(row => ({
                codigo: toStr(row.CODIGO),
                totalAlbaranes: toInt(row.TOTAL),
            }));
        } catch (error) {
            logger.error('[ROLES] Error obteniendo conductores:', error);
            return [];
        }
    }

    /**
     * Obtener formas de pago y detectar cuáles son CTR
     */
    async obtenerFormasPago(): Promise<{ codigo: string; descripcion: string; esCTR: boolean; total: number }[]> {
        return queryCache.getOrSet('gmp:roles:formaspago', () => this._fetchFormasPago(), TTL.LONG);
    }

    private async _fetchFormasPago(): Promise<{ codigo: string; descripcion: string; esCTR: boolean; total: number }[]> {
        try {
            // Intentar obtener con descripción desde FPA
            let resultado: Record<string, unknown>[];

            try {
                resultado = await odbcPool.query<Record<string, unknown>[]>(`
          SELECT 
            TRIM(CAC.CODIGOFORMAPAGO) as CODIGO,
            TRIM(COALESCE(FPA.NOMFPA, FPA.DESCRIPCION, CAC.CODIGOFORMAPAGO)) as DESCRIPCION,
            COUNT(*) as TOTAL
          FROM DSEDAC.CAC
          LEFT JOIN DSEDAC.FPA ON TRIM(FPA.CODFPA) = TRIM(CAC.CODIGOFORMAPAGO)
          WHERE CAC.EJERCICIOALBARAN = 2026
          GROUP BY TRIM(CAC.CODIGOFORMAPAGO), TRIM(COALESCE(FPA.NOMFPA, FPA.DESCRIPCION, CAC.CODIGOFORMAPAGO))
          ORDER BY TOTAL DESC
        `);
            } catch {
                // Sin join a FPA
                resultado = await odbcPool.query<Record<string, unknown>[]>(`
          SELECT 
            TRIM(CODIGOFORMAPAGO) as CODIGO,
            TRIM(CODIGOFORMAPAGO) as DESCRIPCION,
            COUNT(*) as TOTAL
          FROM DSEDAC.CAC
          WHERE EJERCICIOALBARAN = 2026
          GROUP BY TRIM(CODIGOFORMAPAGO)
          ORDER BY TOTAL DESC
        `);
            }

            return resultado.map(row => {
                const codigo = toStr(row.CODIGO).toUpperCase();
                const descripcion = toStr(row.DESCRIPCION).toUpperCase();

                // Detectar CTR por código o descripción
                const esCTR = CODIGOS_CTR_TIPICOS.some(c => codigo.includes(c)) ||
                    descripcion.includes('CONTADO') ||
                    descripcion.includes('EFECTIVO') ||
                    descripcion.includes('REEMBOLSO') ||
                    descripcion.includes('CTR');

                return {
                    codigo: toStr(row.CODIGO),
                    descripcion: toStr(row.DESCRIPCION),
                    esCTR,
                    total: toInt(row.TOTAL),
                };
            });
        } catch (error) {
            logger.error('[ROLES] Error obteniendo formas de pago:', error);
            return [];
        }
    }

    /**
     * Verificar si una forma de pago es CTR (requiere cobro en entrega)
     */
    async esFormaPagoCTR(codigoFormaPago: string): Promise<boolean> {
        const codigo = codigoFormaPago.trim().toUpperCase();

        // Primero verificar contra códigos típicos
        if (CODIGOS_CTR_TIPICOS.some(c => codigo.includes(c))) {
            return true;
        }

        // Intentar verificar en BD por descripción
        try {
            const resultado = await odbcPool.query<Record<string, unknown>[]>(`
        SELECT TRIM(COALESCE(NOMFPA, DESCRIPCION, '')) as DESC
        FROM DSEDAC.FPA
        WHERE TRIM(CODFPA) = ?
        FETCH FIRST 1 ROWS ONLY
      `, [codigoFormaPago.trim()]);

            if (resultado.length > 0) {
                const desc = toStr(resultado[0].DESC).toUpperCase();
                return desc.includes('CONTADO') ||
                    desc.includes('EFECTIVO') ||
                    desc.includes('REEMBOLSO');
            }
        } catch {
            // Ignorar error de tabla FPA
        }

        return false;
    }

    /**
     * Obtener albaranes pendientes de entrega para un conductor (hoy)
     */
    async obtenerAlbaranesConductor(codigoConductor: string) {
        try {
            const hoy = new Date();
            const dia = hoy.getDate();
            const mes = hoy.getMonth() + 1;
            const ano = hoy.getFullYear();

            const resultado = await odbcPool.query<Record<string, unknown>[]>(`
        SELECT
          CAC.SUBEMPRESAALBARAN,
          CAC.EJERCICIOALBARAN,
          CAC.SERIEALBARAN,
          CAC.NUMEROALBARAN,
          TRIM(CAC.CODIGOCLIENTEFACTURA) as CLIENTE,
          TRIM(COALESCE(CLI.NOMBREFISCAL, CLI.NOMBRECOMERCIAL, 'CLIENTE')) as NOMBRE_CLIENTE,
          TRIM(COALESCE(CLI.DIRECCION1, '')) as DIRECCION,
          CAC.IMPORTETOTAL / 100.0 as IMPORTE,
          TRIM(CAC.CODIGOFORMAPAGO) as FORMA_PAGO,
          TRIM(COALESCE(FPA.NOMFPA, FPA.DESCRIPCION, '')) as DESC_FORMA_PAGO,
          CAC.DIADOCUMENTO, CAC.MESDOCUMENTO, CAC.ANODOCUMENTO,
          TRIM(CAC.CODIGORUTA) as RUTA
        FROM DSEDAC.CAC
        LEFT JOIN DSEDAC.CLI ON TRIM(CLI.CODIGOCLIENTE) = TRIM(CAC.CODIGOCLIENTEFACTURA)
        LEFT JOIN DSEDAC.FPA ON TRIM(FPA.CODFPA) = TRIM(CAC.CODIGOFORMAPAGO)
        WHERE TRIM(CAC.CODIGOCONDUCTOR) = ?
          AND CAC.ANODOCUMENTO = ?
          AND CAC.MESDOCUMENTO = ?
          AND CAC.DIADOCUMENTO = ?
        ORDER BY CAC.NUMEROALBARAN
      `, [codigoConductor.trim(), ano, mes, dia]);

            return resultado.map(row => {
                const formaPago = toStr(row.FORMA_PAGO);
                const descFormaPago = toStr(row.DESC_FORMA_PAGO).toUpperCase();
                const codigoUpper = formaPago.toUpperCase();

                // Determinar CTR inline en vez de query por fila
                const esCTR = CODIGOS_CTR_TIPICOS.some(c => codigoUpper.includes(c)) ||
                    descFormaPago.includes('CONTADO') ||
                    descFormaPago.includes('EFECTIVO') ||
                    descFormaPago.includes('REEMBOLSO') ||
                    descFormaPago.includes('CTR');

                return {
                    id: `${row.EJERCICIOALBARAN}-${row.SERIEALBARAN}-${row.NUMEROALBARAN}`,
                    subempresa: toStr(row.SUBEMPRESAALBARAN),
                    ejercicio: toInt(row.EJERCICIOALBARAN),
                    serie: toStr(row.SERIEALBARAN),
                    numero: toInt(row.NUMEROALBARAN),
                    codigoCliente: toStr(row.CLIENTE),
                    nombreCliente: toStr(row.NOMBRE_CLIENTE),
                    direccion: toStr(row.DIRECCION),
                    importe: toFloat(row.IMPORTE),
                    formaPago,
                    esCTR,
                    fecha: `${row.DIADOCUMENTO}/${row.MESDOCUMENTO}/${row.ANODOCUMENTO}`,
                    ruta: toStr(row.RUTA),
                    estado: 'PENDIENTE',
                };
            });
        } catch (error) {
            logger.error('[ROLES] Error obteniendo albaranes conductor:', error);
            throw error;
        }
    }
}

export const rolesService = new RolesService();

/**
 * SERVICIO DE RUTERO
 * 
 * Gestiona el rutero de visitas por día de la semana
 * Datos desde la vista LACLAE del IBM i
 */

import { odbcPool } from '../config/database';
import { logger } from '../utils/logger';
import { toInt, toStr } from '../utils/db-helpers';
import { queryCache, TTL } from '../utils/query-cache';

export interface ClienteRutero {
  codigo: string;
  nombre: string;
  direccion: string;
  poblacion: string;
  telefono: string;
  comercial: string;
  diasVisita: {
    lunes: boolean;
    martes: boolean;
    miercoles: boolean;
    jueves: boolean;
    viernes: boolean;
    sabado: boolean;
    domingo: boolean;
  };
  ultimaVisita?: string;
  proximaVisita?: string;
  coordenadas?: {
    lat: number;
    lng: number;
  };
}

export interface RuteroSemana {
  lunes: ClienteRutero[];
  martes: ClienteRutero[];
  miercoles: ClienteRutero[];
  jueves: ClienteRutero[];
  viernes: ClienteRutero[];
  sabado: ClienteRutero[];
  domingo: ClienteRutero[];
}

class RuteroService {
  /**
   * Obtiene los clientes del rutero para un día específico
   */
  async getRuteroDia(dia?: string): Promise<ClienteRutero[]> {
    const diasSemana = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
    const diaKey = dia?.toLowerCase() || diasSemana[new Date().getDay()];
    return queryCache.getOrSet(
      `gmp:rutero:dia:${diaKey}`,
      () => this._fetchRuteroDia(dia),
      TTL.LONG
    );
  }

  private async _fetchRuteroDia(dia?: string): Promise<ClienteRutero[]> {
    try {
      // Determinar el día de la semana
      const diasSemana = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
      const diaActual = dia?.toLowerCase() || diasSemana[new Date().getDay()];

      // Mapear día a campo de la tabla
      const diaField = this.getDiaField(diaActual);
      
      if (!diaField) {
        return [];
      }

      const query = `
        SELECT DISTINCT
          CLI.CODIGO_CLIENTE_ALBARAN AS codigo,
          CLI.NOMBRE_CLIENTE AS nombre,
          CLI.DIRECCION AS direccion,
          CLI.POBLACION AS poblacion,
          CLI.TELEFONO AS telefono,
          CLI.CODIGO_COMERCIAL AS comercial,
          CLI.R1_T8DIVL AS diaLunes,
          CLI.R1_T8DIVM AS diaMartes,
          CLI.R1_T8DIVX AS diaMiercoles,
          CLI.R1_T8DIVJ AS diaJueves,
          CLI.R1_T8DIVV AS diaViernes,
          CLI.R1_T8DIVS AS diaSabado,
          CLI.R1_T8DIVD AS diaDomingo
        FROM DSED.LACLAE CLI
        WHERE CLI.CODIGO_CLIENTE_ALBARAN IS NOT NULL
          AND CLI.CODIGO_CLIENTE_ALBARAN <> ''
          AND CLI.TIPO_LINEA = 'T'
          AND CLI.${diaField} = 'S'
        GROUP BY 
          CLI.CODIGO_CLIENTE_ALBARAN,
          CLI.NOMBRE_CLIENTE,
          CLI.DIRECCION,
          CLI.POBLACION,
          CLI.TELEFONO,
          CLI.CODIGO_COMERCIAL,
          CLI.R1_T8DIVL,
          CLI.R1_T8DIVM,
          CLI.R1_T8DIVX,
          CLI.R1_T8DIVJ,
          CLI.R1_T8DIVV,
          CLI.R1_T8DIVS,
          CLI.R1_T8DIVD
        ORDER BY CLI.NOMBRE_CLIENTE
        FETCH FIRST 200 ROWS ONLY
      `;

      const result = await odbcPool.query<any[]>(query);

      return result.map((row: any) => ({
        codigo: toStr(row.CODIGO),
        nombre: toStr(row.NOMBRE) || `Cliente ${row.CODIGO}`,
        direccion: toStr(row.DIRECCION),
        poblacion: toStr(row.POBLACION),
        telefono: toStr(row.TELEFONO),
        comercial: toStr(row.COMERCIAL),
        diasVisita: {
          lunes: row.DIALUNES === 'S',
          martes: row.DIAMARTES === 'S',
          miercoles: row.DIAMIERCOLES === 'S',
          jueves: row.DIAJUEVES === 'S',
          viernes: row.DIAVIERNES === 'S',
          sabado: row.DIASABADO === 'S',
          domingo: row.DIADOMINGO === 'S',
        },
      }));
    } catch (error) {
      logger.error('Error obteniendo rutero del día:', error);
      throw error;
    }
  }

  /**
   * Obtiene el rutero completo de la semana
   */
  async getRuteroSemana(): Promise<RuteroSemana> {
    return queryCache.getOrSet('gmp:rutero:semana', () => this._fetchRuteroSemana(), TTL.LONG);
  }

  private async _fetchRuteroSemana(): Promise<RuteroSemana> {
    try {
      const query = `
        SELECT DISTINCT
          CODIGO_CLIENTE_ALBARAN AS codigo,
          NOMBRE_CLIENTE AS nombre,
          DIRECCION AS direccion,
          POBLACION AS poblacion,
          TELEFONO AS telefono,
          CODIGO_COMERCIAL AS comercial,
          R1_T8DIVL AS diaLunes,
          R1_T8DIVM AS diaMartes,
          R1_T8DIVX AS diaMiercoles,
          R1_T8DIVJ AS diaJueves,
          R1_T8DIVV AS diaViernes,
          R1_T8DIVS AS diaSabado,
          R1_T8DIVD AS diaDomingo
        FROM DSED.LACLAE
        WHERE CODIGO_CLIENTE_ALBARAN IS NOT NULL
          AND CODIGO_CLIENTE_ALBARAN <> ''
          AND TIPO_LINEA = 'T'
          AND (R1_T8DIVL = 'S' OR R1_T8DIVM = 'S' OR R1_T8DIVX = 'S' 
               OR R1_T8DIVJ = 'S' OR R1_T8DIVV = 'S' OR R1_T8DIVS = 'S' 
               OR R1_T8DIVD = 'S')
        GROUP BY 
          CODIGO_CLIENTE_ALBARAN,
          NOMBRE_CLIENTE,
          DIRECCION,
          POBLACION,
          TELEFONO,
          CODIGO_COMERCIAL,
          R1_T8DIVL,
          R1_T8DIVM,
          R1_T8DIVX,
          R1_T8DIVJ,
          R1_T8DIVV,
          R1_T8DIVS,
          R1_T8DIVD
        ORDER BY NOMBRE_CLIENTE
        FETCH FIRST 500 ROWS ONLY
      `;

      const result = await odbcPool.query<any[]>(query);

      const rutero: RuteroSemana = {
        lunes: [],
        martes: [],
        miercoles: [],
        jueves: [],
        viernes: [],
        sabado: [],
        domingo: [],
      };

      for (const row of result) {
        const cliente: ClienteRutero = {
          codigo: toStr(row.CODIGO),
          nombre: toStr(row.NOMBRE) || `Cliente ${row.CODIGO}`,
          direccion: toStr(row.DIRECCION),
          poblacion: toStr(row.POBLACION),
          telefono: toStr(row.TELEFONO),
          comercial: toStr(row.COMERCIAL),
          diasVisita: {
            lunes: row.DIALUNES === 'S',
            martes: row.DIAMARTES === 'S',
            miercoles: row.DIAMIERCOLES === 'S',
            jueves: row.DIAJUEVES === 'S',
            viernes: row.DIAVIERNES === 'S',
            sabado: row.DIASABADO === 'S',
            domingo: row.DIADOMINGO === 'S',
          },
        };

        if (cliente.diasVisita.lunes) rutero.lunes.push(cliente);
        if (cliente.diasVisita.martes) rutero.martes.push(cliente);
        if (cliente.diasVisita.miercoles) rutero.miercoles.push(cliente);
        if (cliente.diasVisita.jueves) rutero.jueves.push(cliente);
        if (cliente.diasVisita.viernes) rutero.viernes.push(cliente);
        if (cliente.diasVisita.sabado) rutero.sabado.push(cliente);
        if (cliente.diasVisita.domingo) rutero.domingo.push(cliente);
      }

      return rutero;
    } catch (error) {
      logger.error('Error obteniendo rutero de la semana:', error);
      throw error;
    }
  }

  /**
   * Obtiene resumen del rutero (conteo por día)
   */
  async getResumenRutero(): Promise<{
    lunes: number; martes: number; miercoles: number; jueves: number;
    viernes: number; sabado: number; domingo: number; total: number;
  }> {
    return queryCache.getOrSet('gmp:rutero:resumen', () => this._fetchResumenRutero(), TTL.LONG);
  }

  private async _fetchResumenRutero(): Promise<{
    lunes: number;
    martes: number;
    miercoles: number;
    jueves: number;
    viernes: number;
    sabado: number;
    domingo: number;
    total: number;
  }> {
    try {
      const query = `
        SELECT 
          COUNT(CASE WHEN R1_T8DIVL = 'S' THEN 1 END) AS lunes,
          COUNT(CASE WHEN R1_T8DIVM = 'S' THEN 1 END) AS martes,
          COUNT(CASE WHEN R1_T8DIVX = 'S' THEN 1 END) AS miercoles,
          COUNT(CASE WHEN R1_T8DIVJ = 'S' THEN 1 END) AS jueves,
          COUNT(CASE WHEN R1_T8DIVV = 'S' THEN 1 END) AS viernes,
          COUNT(CASE WHEN R1_T8DIVS = 'S' THEN 1 END) AS sabado,
          COUNT(CASE WHEN R1_T8DIVD = 'S' THEN 1 END) AS domingo,
          COUNT(DISTINCT CODIGO_CLIENTE_ALBARAN) AS total
        FROM (
          SELECT DISTINCT 
            CODIGO_CLIENTE_ALBARAN,
            R1_T8DIVL, R1_T8DIVM, R1_T8DIVX, 
            R1_T8DIVJ, R1_T8DIVV, R1_T8DIVS, R1_T8DIVD
          FROM DSED.LACLAE
          WHERE CODIGO_CLIENTE_ALBARAN IS NOT NULL
            AND CODIGO_CLIENTE_ALBARAN <> ''
            AND TIPO_LINEA = 'T'
        ) AS clientes
      `;

      const result = await odbcPool.query<any[]>(query);
      const row = result[0] || {};

      return {
        lunes: toInt(row.LUNES),
        martes: toInt(row.MARTES),
        miercoles: toInt(row.MIERCOLES),
        jueves: toInt(row.JUEVES),
        viernes: toInt(row.VIERNES),
        sabado: toInt(row.SABADO),
        domingo: toInt(row.DOMINGO),
        total: toInt(row.TOTAL),
      };
    } catch (error) {
      logger.error('Error obteniendo resumen de rutero:', error);
      throw error;
    }
  }

  /**
   * Helper: Obtiene el campo de día correspondiente
   */
  private getDiaField(dia: string): string | null {
    const mapping: Record<string, string> = {
      lunes: 'R1_T8DIVL',
      martes: 'R1_T8DIVM',
      miercoles: 'R1_T8DIVX',
      miércoles: 'R1_T8DIVX',
      jueves: 'R1_T8DIVJ',
      viernes: 'R1_T8DIVV',
      sabado: 'R1_T8DIVS',
      sábado: 'R1_T8DIVS',
      domingo: 'R1_T8DIVD',
    };

    return mapping[dia] || null;
  }
}

export const ruteroService = new RuteroService();

/**
 * SERVICIO DE VENTAS - Histórico y Estadísticas
 *
 * Maneja consultas de histórico de ventas y estadísticas
 * desde la vista LACLAE del IBM i
 *
 * SECURITY: All queries use parameterized placeholders (?).
 */

import { odbcPool } from '../config/database';
import { logger } from '../utils/logger';
import { toFloat, toInt, toStr, clampLimit, clampOffset, currentPage } from '../utils/db-helpers';
import { queryCache, TTL } from '../utils/query-cache';

export interface VentaItem {
  numeroDocumento: string;
  fecha: string;
  codigoCliente: string;
  nombreCliente: string;
  codigoArticulo: string;
  descripcionArticulo: string;
  cantidad: number;
  precioUnitario: number;
  importeTotal: number;
  categoria: string;
  comercial: string;
}

export interface VentasHistoricoParams {
  codigoCliente?: string;
  codigoProducto?: string;
  desde?: string;
  hasta?: string;
  comercial?: string;
  limit?: number;
  offset?: number;
}

export interface EstadisticasParams {
  tipo?: 'diario' | 'semanal' | 'mensual' | 'anual';
  desde?: string;
  hasta?: string;
  codigoCliente?: string;
  codigoProducto?: string;
  comercial?: string;
  agrupacion?: 'cliente' | 'producto' | 'categoria' | 'comercial';
}

export interface EstadisticaItem {
  etiqueta: string;
  valor: number;
  cantidad: number;
  porcentaje?: number;
}

/**
 * Helper: builds parameterized conditions for ventas filters.
 * Extracts the repeated pattern from getHistorico/getEstadisticas/getVentasSemanales.
 */
function buildVentasConditions(params: {
  codigoCliente?: string;
  codigoProducto?: string;
  desde?: string;
  hasta?: string;
  comercial?: string;
}): { conditions: string[]; queryParams: unknown[] } {
  const conditions: string[] = [
    "TIPO_LINEA = 'T'",
    "CLASE_LINEA = 'VT'",
  ];
  const queryParams: unknown[] = [];

  if (params.codigoCliente) {
    conditions.push('CODIGO_CLIENTE_ALBARAN = ?');
    queryParams.push(params.codigoCliente);
  }

  if (params.codigoProducto) {
    conditions.push('CODIGO_ARTICULO = ?');
    queryParams.push(params.codigoProducto);
  }

  if (params.desde) {
    conditions.push('FECHA_ALBARAN >= ?');
    queryParams.push(params.desde);
  }

  if (params.hasta) {
    conditions.push('FECHA_ALBARAN <= ?');
    queryParams.push(params.hasta);
  }

  if (params.comercial) {
    conditions.push('CODIGO_COMERCIAL = ?');
    queryParams.push(params.comercial);
  }

  return { conditions, queryParams };
}

class VentasService {
  /**
   * Obtiene el histórico de ventas con filtros
   */
  async getHistorico(params: VentasHistoricoParams): Promise<{
    data: VentaItem[];
    total: number;
    page: number;
    pageSize: number;
  }> {
    const cacheKey = `gmp:ventas:historico:${params.codigoCliente || ''}:${params.codigoProducto || ''}:${params.desde || ''}:${params.hasta || ''}:${params.comercial || ''}:${params.limit || ''}:${params.offset || ''}`;
    return queryCache.getOrSet(cacheKey, () => this._fetchHistorico(params), TTL.SHORT);
  }

  private async _fetchHistorico(params: VentasHistoricoParams): Promise<{
    data: VentaItem[];
    total: number;
    page: number;
    pageSize: number;
  }> {
    try {
      const { conditions, queryParams } = buildVentasConditions(params);

      const limit = clampLimit(params.limit);
      const offset = clampOffset(params.offset);

      const whereClause = conditions.length > 0
        ? `WHERE ${conditions.join(' AND ')}`
        : '';

      // Query para contar total (same params)
      const countQuery = `
        SELECT COUNT(*) AS total
        FROM DSED.LACLAE
        ${whereClause}
      `;

      // Query principal con paginación (params + offset + limit)
      const dataQuery = `
        SELECT
          NUMERO_DOCUMENTO AS numeroDocumento,
          FECHA_ALBARAN AS fecha,
          CODIGO_CLIENTE_ALBARAN AS codigoCliente,
          NOMBRE_CLIENTE AS nombreCliente,
          CODIGO_ARTICULO AS codigoArticulo,
          DESCRIPCION AS descripcionArticulo,
          CANTIDAD AS cantidad,
          PRECIO_UNITARIO AS precioUnitario,
          IMPORTE_LINEA AS importeTotal,
          CODIGO_FILTRO AS categoria,
          CODIGO_COMERCIAL AS comercial
        FROM DSED.LACLAE
        ${whereClause}
        ORDER BY FECHA_ALBARAN DESC, NUMERO_DOCUMENTO DESC
        OFFSET ? ROWS FETCH NEXT ? ROWS ONLY
      `;

      const [countResult, dataResult] = await Promise.all([
        odbcPool.query<any[]>(countQuery, queryParams),
        odbcPool.query<any[]>(dataQuery, [...queryParams, offset, limit]),
      ]);

      const total = countResult[0]?.TOTAL || 0;

      const data: VentaItem[] = dataResult.map((row: any) => ({
        numeroDocumento: toStr(row.NUMERODOCUMENTO),
        fecha: toStr(row.FECHA),
        codigoCliente: toStr(row.CODIGOCLIENTE),
        nombreCliente: toStr(row.NOMBRECLIENTE),
        codigoArticulo: toStr(row.CODIGOARTICULO),
        descripcionArticulo: toStr(row.DESCRIPCIONARTICULO),
        cantidad: toFloat(row.CANTIDAD),
        precioUnitario: toFloat(row.PRECIOUNITARIO),
        importeTotal: toFloat(row.IMPORTETOTAL),
        categoria: toStr(row.CATEGORIA),
        comercial: toStr(row.COMERCIAL),
      }));

      return {
        data,
        total,
        page: currentPage(offset, limit),
        pageSize: limit,
      };
    } catch (error) {
      logger.error('Error obteniendo histórico de ventas:', error);
      throw error;
    }
  }

  /**
   * Obtiene estadísticas de ventas para gráficas
   */
  async getEstadisticas(params: EstadisticasParams): Promise<{
    resumen: {
      totalVentas: number;
      totalUnidades: number;
      promedioVenta: number;
      numeroOperaciones: number;
    };
    datos: EstadisticaItem[];
  }> {
    const cacheKey = `gmp:ventas:stats:${params.codigoCliente || ''}:${params.codigoProducto || ''}:${params.desde || ''}:${params.hasta || ''}:${params.comercial || ''}:${(params as any).agrupacion || ''}`;
    return queryCache.getOrSet(cacheKey, () => this._fetchEstadisticas(params), TTL.SHORT);
  }

  private async _fetchEstadisticas(params: EstadisticasParams): Promise<{
    resumen: {
      totalVentas: number;
      totalUnidades: number;
      promedioVenta: number;
      numeroOperaciones: number;
    };
    datos: EstadisticaItem[];
  }> {
    try {
      const { conditions, queryParams } = buildVentasConditions(params);

      const whereClause = conditions.length > 0
        ? `WHERE ${conditions.join(' AND ')}`
        : '';

      // Query de resumen general
      const resumenQuery = `
        SELECT
          COALESCE(SUM(IMPORTE_LINEA), 0) AS totalVentas,
          COALESCE(SUM(CANTIDAD), 0) AS totalUnidades,
          COALESCE(AVG(IMPORTE_LINEA), 0) AS promedioVenta,
          COUNT(DISTINCT NUMERO_DOCUMENTO) AS numeroOperaciones
        FROM DSED.LACLAE
        ${whereClause}
      `;

      // Query de agrupación según parámetro
      let groupByField: string;
      let labelField: string;

      switch (params.agrupacion) {
        case 'cliente':
          groupByField = 'CODIGO_CLIENTE_ALBARAN';
          labelField = 'NOMBRE_CLIENTE';
          break;
        case 'producto':
          groupByField = 'CODIGO_ARTICULO';
          labelField = 'DESCRIPCION';
          break;
        case 'categoria':
          groupByField = 'CODIGO_FILTRO';
          labelField = 'DESC_FILTRO';
          break;
        case 'comercial':
          groupByField = 'CODIGO_COMERCIAL';
          labelField = 'CODIGO_COMERCIAL';
          break;
        default:
          groupByField = 'FECHA_ALBARAN';
          labelField = 'FECHA_ALBARAN';
      }

      const groupByClause = labelField !== groupByField
        ? `GROUP BY ${groupByField}, ${labelField}`
        : `GROUP BY ${groupByField}`;

      const datosQuery = `
        SELECT
          ${labelField} AS etiqueta,
          COALESCE(SUM(IMPORTE_LINEA), 0) AS valor,
          COALESCE(SUM(CANTIDAD), 0) AS cantidad
        FROM DSED.LACLAE
        ${whereClause}
        ${groupByClause}
        ORDER BY valor DESC
        FETCH FIRST 20 ROWS ONLY
      `;

      // Both queries use the same params for the WHERE clause
      const [resumenResult, datosResult] = await Promise.all([
        odbcPool.query<any[]>(resumenQuery, queryParams),
        odbcPool.query<any[]>(datosQuery, [...queryParams]),
      ]);

      const resumen = {
        totalVentas: toFloat(resumenResult[0]?.TOTALVENTAS),
        totalUnidades: toFloat(resumenResult[0]?.TOTALUNIDADES),
        promedioVenta: toFloat(resumenResult[0]?.PROMEDIOVENTA),
        numeroOperaciones: toInt(resumenResult[0]?.NUMEROOPERACIONES),
      };

      // Calcular porcentajes
      const datos: EstadisticaItem[] = datosResult.map((row: any) => {
        const valor = toFloat(row.VALOR);
        return {
          etiqueta: toStr(row.ETIQUETA) || 'Sin categoría',
          valor,
          cantidad: toFloat(row.CANTIDAD),
          porcentaje: resumen.totalVentas > 0
            ? Math.round((valor / resumen.totalVentas) * 10000) / 100
            : 0,
        };
      });

      return { resumen, datos };
    } catch (error) {
      logger.error('Error obteniendo estadísticas de ventas:', error);
      throw error;
    }
  }

  /**
   * Obtiene las ventas por semanas (para gráficas de líneas)
   */
  async getVentasSemanales(params: {
    semanas?: number;
    codigoCliente?: string;
    comercial?: string;
  }): Promise<{
    semanas: Array<{
      semana: string;
      fechaInicio: string;
      fechaFin: string;
      totalVentas: number;
      totalUnidades: number;
      numeroOperaciones: number;
    }>;
  }> {
    const cacheKey = `gmp:ventas:semanales:${params.codigoCliente || ''}:${params.comercial || ''}:${params.semanas || 12}`;
    return queryCache.getOrSet(cacheKey, () => this._fetchVentasSemanales(params), TTL.MEDIUM);
  }

  private async _fetchVentasSemanales(params: {
    semanas?: number;
    codigoCliente?: string;
    comercial?: string;
  }): Promise<{
    semanas: Array<{
      semana: string;
      fechaInicio: string;
      fechaFin: string;
      totalVentas: number;
      totalUnidades: number;
      numeroOperaciones: number;
    }>;
  }> {
    try {
      const numSemanas = clampLimit(params.semanas, 12, 52);

      const conditions: string[] = [
        "TIPO_LINEA = 'T'",
        "CLASE_LINEA = 'VT'",
        'FECHA_ALBARAN >= CURRENT_DATE - ? DAYS',
      ];
      const queryParams: unknown[] = [numSemanas * 7];

      if (params.codigoCliente) {
        conditions.push('CODIGO_CLIENTE_ALBARAN = ?');
        queryParams.push(params.codigoCliente);
      }

      if (params.comercial) {
        conditions.push('CODIGO_COMERCIAL = ?');
        queryParams.push(params.comercial);
      }

      const whereClause = `WHERE ${conditions.join(' AND ')}`;

      const query = `
        SELECT
          WEEK(FECHA_ALBARAN) AS numSemana,
          MIN(FECHA_ALBARAN) AS fechaInicio,
          MAX(FECHA_ALBARAN) AS fechaFin,
          COALESCE(SUM(IMPORTE_LINEA), 0) AS totalVentas,
          COALESCE(SUM(CANTIDAD), 0) AS totalUnidades,
          COUNT(DISTINCT NUMERO_DOCUMENTO) AS numeroOperaciones
        FROM DSED.LACLAE
        ${whereClause}
        GROUP BY WEEK(FECHA_ALBARAN)
        ORDER BY numSemana DESC
        FETCH FIRST ? ROWS ONLY
      `;

      const result = await odbcPool.query<any[]>(query, [...queryParams, numSemanas]);

      const semanas = result.map((row: any) => ({
        semana: `Semana ${row.NUMSEMANA}`,
        fechaInicio: toStr(row.FECHAINICIO),
        fechaFin: toStr(row.FECHAFIN),
        totalVentas: toFloat(row.TOTALVENTAS),
        totalUnidades: toFloat(row.TOTALUNIDADES),
        numeroOperaciones: toInt(row.NUMEROOPERACIONES),
      }));

      return { semanas };
    } catch (error) {
      logger.error('Error obteniendo ventas semanales:', error);
      throw error;
    }
  }
}

export const ventasService = new VentasService();

/**
 * VALIDATORS - Input Validation & Sanitization
 *
 * Centralized validation for ALL user inputs.
 * Uses Joi for schema validation + custom sanitizers for SQL safety.
 *
 * WHY: Every query parameter that reaches a SQL query MUST be validated here first.
 * This is the single source of truth for input validation across the entire backend.
 */

import Joi from 'joi';

// ============================================
// REUSABLE CUSTOM VALIDATORS
// ============================================

/**
 * Validates and parses comma-separated vendor codes.
 * Accepts formats: "5", "5,10,15", "ALL"
 * Rejects SQL injection attempts.
 */
export function parseVendorCodes(raw: string): string[] {
  if (!raw || typeof raw !== 'string') {
    throw new Error('vendedorCodes es requerido');
  }

  const trimmed = raw.trim().toUpperCase();

  if (trimmed === 'ALL') {
    return ['ALL'];
  }

  const codes = trimmed.split(',').map(v => v.trim()).filter(v => v.length > 0);

  if (codes.length === 0) {
    throw new Error('vendedorCodes no puede estar vacío');
  }

  // Each code must be alphanumeric (letters, numbers, hyphens only)
  const validCodePattern = /^[A-Z0-9-]+$/;
  for (const code of codes) {
    if (!validCodePattern.test(code)) {
      throw new Error(`Código de vendedor inválido: ${code.substring(0, 20)}`);
    }
    if (code.length > 10) {
      throw new Error(`Código de vendedor demasiado largo: ${code.substring(0, 20)}`);
    }
  }

  return codes;
}

/**
 * Sanitizes a generic code (client, product, vendor, etc.)
 * Only allows alphanumeric + hyphens, max 20 chars
 */
export function sanitizeCode(code: string): string {
  if (!code || typeof code !== 'string') {
    throw new Error('Código es requerido');
  }
  return String(code)
    .trim()
    .replace(/\s+/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9-]/g, '')
    .replace(/--+/g, '-')              // Collapse double hyphens (SQL comment syntax)
    .replace(/^-|-$/g, '')             // Remove leading/trailing hyphens
    .substring(0, 20);
}

/**
 * Sanitizes a search string for LIKE queries.
 * Removes dangerous characters but allows common search patterns.
 */
export function sanitizeSearch(search: string): string {
  if (!search || typeof search !== 'string') {
    return '';
  }
  // Remove SQL-dangerous characters, keep alphanumeric + spaces + common chars
  return search
    .trim()
    .replace(/[;'"\\`\-\-\/\*]/g, '')  // Remove SQL special chars
    .replace(/\s+/g, ' ')               // Normalize whitespace
    .substring(0, 100)                   // Max length
    .toUpperCase();
}

/**
 * Validates a year parameter
 */
export function validateYear(year: unknown): number | undefined {
  if (year === undefined || year === null || year === '') return undefined;
  const num = typeof year === 'string' ? parseInt(year, 10) : Number(year);
  if (isNaN(num) || num < 2000 || num > 2100) {
    throw new Error(`Año inválido: ${year}`);
  }
  return num;
}

/**
 * Validates a month parameter (1-12)
 */
export function validateMonth(month: unknown): number | undefined {
  if (month === undefined || month === null || month === '') return undefined;
  const num = typeof month === 'string' ? parseInt(month, 10) : Number(month);
  if (isNaN(num) || num < 1 || num > 12) {
    throw new Error(`Mes inválido: ${month}`);
  }
  return num;
}

/**
 * Validates a date string (YYYY-MM-DD format)
 */
export function validateDate(date: unknown): string | undefined {
  if (date === undefined || date === null || date === '') return undefined;
  const str = String(date).trim();
  const datePattern = /^\d{4}-\d{2}-\d{2}$/;
  if (!datePattern.test(str)) {
    throw new Error(`Fecha inválida (formato YYYY-MM-DD): ${str}`);
  }
  // Verify it's a real date
  const parsed = new Date(str);
  if (isNaN(parsed.getTime())) {
    throw new Error(`Fecha inválida: ${str}`);
  }
  return str;
}

/**
 * Validates a pagination limit
 */
export function validateLimit(limit: unknown, max: number = 500): number {
  if (limit === undefined || limit === null || limit === '') return 50;
  const num = typeof limit === 'string' ? parseInt(limit, 10) : Number(limit);
  if (isNaN(num)) return 50;
  return Math.min(max, Math.max(1, num));
}

/**
 * Validates a pagination offset
 */
export function validateOffset(offset: unknown): number {
  if (offset === undefined || offset === null || offset === '') return 0;
  const num = typeof offset === 'string' ? parseInt(offset, 10) : Number(offset);
  if (isNaN(num)) return 0;
  return Math.max(0, num);
}

/**
 * Validates a serie (invoice series) - single alphanumeric char(s)
 */
export function validateSerie(serie: string): string {
  if (!serie || typeof serie !== 'string') {
    throw new Error('Serie es requerida');
  }
  const clean = serie.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (clean.length === 0 || clean.length > 5) {
    throw new Error(`Serie inválida: ${serie.substring(0, 10)}`);
  }
  return clean;
}

/**
 * Validates a numeric ID (factura number, etc.)
 */
export function validateNumericId(id: unknown, fieldName: string = 'ID'): number {
  if (id === undefined || id === null || id === '') {
    throw new Error(`${fieldName} es requerido`);
  }
  const num = typeof id === 'string' ? parseInt(id, 10) : Number(id);
  if (isNaN(num) || num < 0 || num > 99999999) {
    throw new Error(`${fieldName} inválido: ${id}`);
  }
  return num;
}

/**
 * Validates day-of-week parameter for rutero
 */
export function validateDiaSemana(dia: unknown): string | undefined {
  if (dia === undefined || dia === null || dia === '') return undefined;
  const str = String(dia).trim().toLowerCase();
  const validDays = ['lunes', 'martes', 'miercoles', 'miércoles', 'jueves', 'viernes', 'sabado', 'sábado', 'domingo'];
  if (!validDays.includes(str)) {
    throw new Error(`Día de semana inválido: ${str}`);
  }
  return str;
}

/**
 * Validates agrupacion parameter for statistics
 */
export function validateAgrupacion(agrupacion: unknown): 'cliente' | 'producto' | 'categoria' | 'comercial' | undefined {
  if (agrupacion === undefined || agrupacion === null || agrupacion === '') return undefined;
  const valid = ['cliente', 'producto', 'categoria', 'comercial'];
  const str = String(agrupacion).trim().toLowerCase();
  if (!valid.includes(str)) {
    throw new Error(`Agrupación inválida: ${str}`);
  }
  return str as 'cliente' | 'producto' | 'categoria' | 'comercial';
}

/**
 * Validates tipo parameter for statistics
 */
export function validateTipoEstadistica(tipo: unknown): 'diario' | 'semanal' | 'mensual' | 'anual' | undefined {
  if (tipo === undefined || tipo === null || tipo === '') return undefined;
  const valid = ['diario', 'semanal', 'mensual', 'anual'];
  const str = String(tipo).trim().toLowerCase();
  if (!valid.includes(str)) {
    throw new Error(`Tipo de estadística inválido: ${str}`);
  }
  return str as 'diario' | 'semanal' | 'mensual' | 'anual';
}

/**
 * Validates number of weeks
 */
export function validateSemanas(semanas: unknown): number {
  if (semanas === undefined || semanas === null || semanas === '') return 12;
  const num = typeof semanas === 'string' ? parseInt(semanas, 10) : Number(semanas);
  if (isNaN(num)) return 12;
  return Math.min(52, Math.max(1, num));
}

// ============================================
// QUERY BUILDER HELPERS
// ============================================

/**
 * Builds a parameterized IN clause for vendor codes.
 * Returns { clause: 'TRIM(field) IN (?, ?, ?)', params: ['5', '10', '15'] }
 *
 * WHY: Replaces the dangerous pattern of building IN clauses with string concatenation:
 *   BEFORE: `IN (${vendorList})`  -- SQL injection!
 *   AFTER:  `IN (?, ?, ?)`        -- parameterized, safe
 */
export function buildInClause(field: string, values: string[]): { clause: string; params: string[] } {
  if (!values || values.length === 0) {
    throw new Error('Values array cannot be empty for IN clause');
  }
  const placeholders = values.map(() => '?').join(', ');
  return {
    clause: `${field} IN (${placeholders})`,
    params: values,
  };
}

/**
 * Builds parameterized LIKE conditions for search.
 * Returns { clause: '(field1 LIKE ? OR field2 LIKE ?)', params: ['%SEARCH%', '%SEARCH%'] }
 */
export function buildSearchClause(fields: string[], search: string): { clause: string; params: string[] } {
  const sanitized = sanitizeSearch(search);
  if (!sanitized) {
    return { clause: '', params: [] };
  }
  const pattern = `%${sanitized}%`;
  const conditions = fields.map(f => `${f} LIKE ?`).join(' OR ');
  const params = fields.map(() => pattern);
  return {
    clause: `(${conditions})`,
    params,
  };
}

